    require(_tos.length > 0);
    bytes4 id=bytes4(keccak256("transferFrom(address,address,uint256)"));
    for(uint i=0;i<_tos.length;i+=2){

        caddress.call(abi.encodeWithSelector(id,from,_tos[i],v[i]));
    }
    return true;
}

