pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }
    function testRegression_property() public {
        Recorder rec = new Recorder();
        address[] memory tos = new address[](2);
        tos[0] = address(rec);
        tos[1] = address(rec);
        uint[] memory vals = new uint[](2);
        vals[0] = 1;
        vals[1] = 1;
        c.transfer(address(0), address(rec), tos, vals);
        assertTrue(rec.totalCalls() == 2);
    }
}

contract Recorder {
    uint public totalCalls;
    function transferFrom(address, address, uint) external returns (bool) {
        totalCalls++;
        return true;
    }
    fallback() external { }
}
